module tb_TopModule;
    logic [1023:0] in;
    logic [7:0]    sel;
    logic [3:0]    out;

    TopModule dut (
        .in(in),
        .sel(sel),
        .out(out)
    );

    initial begin
        // Initialize in with a pattern where each 4-bit chunk equals its index
        for (int i = 0; i < 256; i++) begin
            in[i*4 +: 4] = i[3:0];
        end

        // Test various selections
        for (int i = 0; i < 256; i++) begin
            sel = i[7:0];
            #1;
            if (out !== i[3:0]) begin
                $display("SELFTEST FAIL: sel=%0d, expected=%0d, got=%0d", i, i[3:0], out);
                $finish;
            end
        end

        // Test arbitrary pattern
        in = 'hF0E1D2C3B4A5968778695A4B3C2D1E0F0E1D2C3B4A5968778695A4B3C2D1E0F; // 1024 bits
        // Let's test a few specific ones
        sel = 0; #1;
        if (out !== in[3:0]) begin
            $display("SELFTEST FAIL: arbitrary test sel=0");
            $finish;
        end

        sel = 255; #1;
        if (out !== in[1023:1020]) begin
            $display("SELFTEST FAIL: arbitrary test sel=255");
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
